const n=[{id:"packet-ged-math-foundations-00",programId:"ged",subject:"Mathematical Reasoning",moduleId:"math-foundations",title:"Number Sense First: Fractions, Decimals, Percent, Ratios, and Powers",estimatedMinutes:60,voiceIntro:"We start where every math score starts: knowing what a number means. You may listen, write, use scratch paper, and explain each answer in your own everyday words.",objectives:["Convert between fractions, decimals, and percent","Solve ratio, rate, and proportion problems","Evaluate exponents and square roots in real situations"],vocabulary:["fraction","percent","ratio","proportion","exponent","square root"],miniLesson:["A fraction, a decimal, and a percent can describe the very same amount; 3/4 equals 0.75 equals 75 percent.","To find a percent of a number, change the percent to a decimal and multiply.","A ratio compares two quantities, and a proportion sets two equal ratios so one missing value can be found by cross multiplying.","An exponent counts repeated multiplication, and a square root asks which number multiplied by itself gives the value under the symbol.","In multi-step problems, name the question first, then solve one step at a time and label every result with its unit."],items:[{id:"gm-nf1",type:"multiple_choice",prompt:"A worker finished 3 of 5 assigned deliveries. What percent is complete?",choices:["35%","53%","60%","75%"],answer:"60%",explanation:"3 ÷ 5 = 0.6, and 0.6 as a percent is 60%."},{id:"gm-nf2",type:"short_response",prompt:"A $48 tool is marked 25% off. Find the sale price and show your steps.",answer:"$36",explanation:"25% of 48 is 0.25 × 48 = 12, and 48 − 12 = 36 dollars."},{id:"gm-nf3",type:"short_response",prompt:"A recipe uses 2 cups of rice for 3 people. How much rice is needed for 12 people?",answer:"8 cups",explanation:"Set 2/3 = x/12. Cross multiplying gives 3x = 24, so x = 8 cups."},{id:"gm-nf4",type:"multiple_choice",prompt:"What is the value of 4³ − √49?",choices:["5","12","57","64"],answer:"57",explanation:"4³ = 64 and √49 = 7, so 64 − 7 = 57."},{id:"gm-nf5",type:"constructed_response",prompt:"A phone plan costs $35 per month plus a one-time $18 fee. Find the total for 6 months and explain how you checked that the answer is reasonable.",answer:"$228",explanation:"6 × 35 = 210, plus the single 18-dollar fee gives 228. Estimating 6 × 35 as about 210 confirms the result is reasonable."}],masteryPercent:80,evidenceRequired:"Four correct answers with visible steps, labeled units or dollar signs, and one written or recorded reasonableness check.",correctionPath:["Restate what the question is asking","Write the numbers in one consistent form","Show each step on its own line","Recheck the operation chosen","Explain in your own words why the answer is reasonable"],printSections:["Plain-language number chart","Worked example","Guided practice","Independent evidence","Answer and correction page"]},{id:"packet-ged-science-practices-00",programId:"ged",subject:"Science",moduleId:"science-practices",title:"Think Like a Scientist: Questions, Variables, Controls, and Claims",estimatedMinutes:60,voiceIntro:"Before we read any science data, we learn how a fair test is built. Listen or read, then say out loud what was changed, what was measured, and what was kept the same.",objectives:["Write a testable question and hypothesis","Identify independent, dependent, and controlled variables","Judge whether a claim is supported by the evidence collected"],vocabulary:["hypothesis","independent variable","dependent variable","control","evidence"],miniLesson:["A testable question can be answered by collecting measurements, not by opinion.","A hypothesis predicts a relationship and can be written as an if-then statement.","The independent variable is what the investigator changes; the dependent variable is what gets measured.","Controlled variables are kept the same so any difference in results can be traced to the one change.","A supported claim stays inside what was actually tested, measured, and observed."],items:[{id:"gs-sp1",type:"multiple_choice",prompt:"Which question is testable through an experiment?",choices:["Is fresh air pleasant?","Do plants grow taller with 6 hours of light than with 2 hours?","Should everyone garden?","Is soil beautiful?"],answer:"Do plants grow taller with 6 hours of light than with 2 hours?",explanation:"Only that question names a change and a measurable outcome."},{id:"gs-sp2",type:"short_response",prompt:"A student tests how salt affects how quickly water boils. Name the independent and dependent variables.",answer:"Independent: amount of salt added. Dependent: time to boil.",explanation:"The salt is deliberately changed and the boiling time is measured as a result."},{id:"gs-sp3",type:"short_response",prompt:"List two variables that must be kept the same in that boiling test.",answer:"Volume of water and the heat setting used.",explanation:"Holding water amount and heat constant keeps salt as the only intended difference."},{id:"gs-sp4",type:"multiple_choice",prompt:"Why does an experiment include a control group?",choices:["To make the test longer","To provide a comparison with no treatment","To guarantee the hypothesis is correct","To reduce the cost of materials"],answer:"To provide a comparison with no treatment",explanation:"The untreated group shows what happens without the change being tested."},{id:"gs-sp5",type:"constructed_response",prompt:"A group tested one plant per light level for three days and concluded that light always determines plant height. Explain one flaw and one improvement.",answer:"One plant per group over three days is too small and too short to support an always claim; repeat with several plants over several weeks.",explanation:"A complete answer names the sample or duration limit and proposes a controlled replication instead of overclaiming."}],masteryPercent:80,evidenceRequired:"Four correct responses, a labeled variable list for one investigation, and a written critique that narrows an overstated claim.",correctionPath:["Underline what was changed","Underline what was measured","List what stayed the same","Compare the claim with the data collected","Rewrite the claim to fit only what was tested"],printSections:["Fair-test checklist","Variable organizer","Worked experiment critique","Independent evidence","Answer explanations"],safetyNote:"This packet is reading- and design-based. Do not run chemical, heat, or electrical procedures without a supervising instructor."},{id:"packet-ged-social-civics-00",programId:"ged",subject:"Social Studies",moduleId:"social-civics",title:"How Power Is Shared: Constitution, Branches, Rights, and Policy Evidence",estimatedMinutes:60,voiceIntro:"Today we read government the way the test reads it: through documents. Listen or read, then point to the exact line that proves your answer instead of relying on memory.",objectives:["Explain core constitutional principles","Match powers and checks to the correct branch","Use a primary source as evidence for a civics claim"],vocabulary:["constitution","separation of powers","checks and balances","federalism","primary source"],miniLesson:["Popular sovereignty means government authority comes from the people.","Separation of powers divides the federal government into legislative, executive, and judicial branches.","Checks and balances let each branch limit the others, such as a veto, an override, or judicial review.","Federalism divides authority between national and state governments.","On the GED, a correct civics answer is supported by the supplied document, chart, or quotation."],items:[{id:"gc-c1",type:"multiple_choice",prompt:"Which branch has the constitutional power to write and pass federal laws?",choices:["Executive","Legislative","Judicial","State courts"],answer:"Legislative",explanation:"Congress, the legislative branch, holds the lawmaking power."},{id:"gc-c2",type:"short_response",prompt:"The President vetoes a bill and Congress votes again to pass it. Name the principle being demonstrated.",answer:"Checks and balances",explanation:"A veto followed by a congressional override is one branch limiting another."},{id:"gc-c3",type:"multiple_choice",prompt:"A court rules a state law unconstitutional. This power is called:",choices:["Impeachment","Judicial review","Ratification","Appropriation"],answer:"Judicial review",explanation:"Judicial review is the courts' authority to measure a law against the Constitution."},{id:"gc-c4",type:"short_response",prompt:"Quotation: 'Congress shall make no law ... abridging the freedom of speech, or of the press.' Which right does this protect?",answer:"Freedom of speech and of the press",explanation:"The quoted First Amendment language names both speech and press directly."},{id:"gc-c5",type:"constructed_response",prompt:"A city council votes to fund a new bus route after residents testify about missed work. Explain how this shows citizen participation and name the evidence you used.",answer:"Residents testified and the council responded with a funded route; the evidence is the testimony followed by the funding vote.",explanation:"A complete response links a citizen action to a government decision and cites the stated facts rather than an opinion."}],masteryPercent:80,evidenceRequired:"Four correct responses plus a written explanation that quotes or paraphrases the supplied source for the participation item.",correctionPath:["Name the branch or right in question","Find the exact line in the document","Match the action to the principle","Eliminate answers not supported by the text","Rewrite the answer using the quoted evidence"],printSections:["Branch-and-power chart","Primary-source page with annotation margins","Worked document analysis","Independent evidence","Answer explanations"]},{id:"packet-ged-math-geometry-01",programId:"ged",subject:"Mathematical Reasoning",moduleId:"math-geometry",title:"Measure the Space: Area, Volume, Scale, and Right Triangles",estimatedMinutes:60,voiceIntro:"Today we will measure real spaces. You may listen, sketch, use the formula sheet, and explain each answer in your own words.",objectives:["Select the correct measurement formula","Use scale and units accurately","Check whether a measurement answer is reasonable"],vocabulary:["perimeter","area","volume","scale","hypotenuse"],miniLesson:["Perimeter measures the distance around a shape; area measures the surface inside it.","Volume counts cubic units inside a three-dimensional object.","A scale drawing uses one consistent ratio between the drawing and the real object.","For a right triangle, a² + b² = c², where c is the side opposite the right angle."],items:[{id:"gm-g1",type:"multiple_choice",prompt:"A 12 ft by 9 ft classroom needs new flooring. How many square feet are covered?",choices:["21","42","108","216"],answer:"108",explanation:"Flooring covers area, so multiply 12 × 9 = 108 square feet."},{id:"gm-g2",type:"short_response",prompt:"A rectangular garden is 18 ft long and 11 ft wide. Find its perimeter.",answer:"58 ft",explanation:"Perimeter is 2(18 + 11) = 58 feet."},{id:"gm-g3",type:"short_response",prompt:"A storage box is 4 ft long, 3 ft wide, and 2 ft high. Find its volume.",answer:"24 ft³",explanation:"Volume is length × width × height: 4 × 3 × 2 = 24 cubic feet."},{id:"gm-g4",type:"multiple_choice",prompt:"On a plan, 1 inch represents 8 feet. A wall measures 3.5 inches. What is the real length?",choices:["11.5 ft","24 ft","28 ft","32 ft"],answer:"28 ft",explanation:"Multiply the drawing length by the scale: 3.5 × 8 = 28 feet."},{id:"gm-g5",type:"constructed_response",prompt:"A wheelchair ramp rises 3 ft and runs 4 ft horizontally. Find the ramp length and explain how you checked it.",answer:"5 ft",explanation:"Use 3² + 4² = c². Since 9 + 16 = 25, c = 5 feet. The hypotenuse is correctly longer than either leg."}],masteryPercent:80,evidenceRequired:"Four correct answers, labeled units, and a written or recorded explanation for the right-triangle item.",correctionPath:["Circle the quantity being requested","Choose a formula from the reference sheet","Substitute values with units","Rework one parallel problem","Explain why the corrected answer is reasonable"],printSections:["Plain-language formula box","Worked example","Guided practice","Independent evidence","Answer and correction page"]},{id:"packet-ged-rla-reading-01",programId:"ged",subject:"Reasoning Through Language Arts",moduleId:"rla-reading",title:"Read for Meaning: Main Idea, Inference, Tone, and Comparison",estimatedMinutes:60,voiceIntro:"Listen to the passage or read it yourself. Pause after each paragraph and say what changed, what mattered, and what the author wants you to understand.",objectives:["Identify a central idea and supporting details","Make an inference using text evidence","Compare tone and purpose across short texts"],vocabulary:["central idea","inference","tone","purpose","evidence"],miniLesson:["The central idea is the most important point developed across the whole text.","An inference combines a text clue with reasonable background knowledge.","Tone is the author's attitude, revealed through word choice and detail.","Strong answers point to exact words or facts instead of relying on memory or opinion."],items:[{id:"gr-r1",type:"short_response",prompt:"Passage: A neighborhood tool library began with 40 donated tools. After one year, 310 households had borrowed equipment and members had completed 76 repairs together. State the central idea.",answer:"The tool library grew into a useful shared community resource.",explanation:"Both the borrowing and repair details show the program's community usefulness and growth."},{id:"gr-r2",type:"multiple_choice",prompt:"Which detail best supports the central idea?",choices:["The tools were donated","The library began with 40 tools","310 households borrowed equipment","The program lasted one year"],answer:"310 households borrowed equipment",explanation:"The number of participating households most directly proves broad community use."},{id:"gr-r3",type:"short_response",prompt:"What can be inferred about why households joined the tool library?",answer:"They likely needed occasional access to tools without buying each one.",explanation:"Borrowing shared equipment supports the inference that access and cost mattered."},{id:"gr-r4",type:"multiple_choice",prompt:"The phrase 'members completed 76 repairs together' creates which tone?",choices:["Hopeless","Cooperative","Suspicious","Angry"],answer:"Cooperative",explanation:"The words members, together, and completed emphasize shared effort."},{id:"gr-r5",type:"constructed_response",prompt:"Compare this program with a traditional store. Give one similarity, one difference, and one text detail.",answer:"Both provide tools; the library lends shared tools while a store sells them. The passage says 310 households borrowed equipment.",explanation:"A complete comparison states a shared function, a meaningful difference, and accurate evidence."}],masteryPercent:80,evidenceRequired:"Four correct responses and a comparison that cites an accurate passage detail.",correctionPath:["Reread the exact sentence","Underline the words that support the answer","Name whether the question asks for idea, detail, inference, tone, or comparison","Eliminate answers that are true but do not answer the question","Revise using one quoted or paraphrased clue"],printSections:["Passage with wide annotation margins","Question-type reminder","Evidence organizer","Independent response","Answer explanations"]},{id:"packet-ged-science-data-01",programId:"ged",subject:"Science",moduleId:"science-data",title:"Make the Data Talk: Tables, Trends, Rates, and Conclusions",estimatedMinutes:60,voiceIntro:"We will read the title, labels, and units before touching the numbers. Then we will describe the pattern and decide what the data can honestly support.",objectives:["Interpret tables and graphs","Calculate change and rate","Distinguish supported conclusions from overclaims"],vocabulary:["trend","rate","variable","outlier","conclusion"],miniLesson:["Read the title, axis or column labels, and units before comparing values.","A trend describes the overall direction; an outlier is a value far from the pattern.","Rate of change compares how much one variable changes over an interval.","A conclusion must stay within the variables, sample, and conditions actually tested."],items:[{id:"gs-d1",type:"short_response",prompt:"A seedling is 4 cm on day 0, 7 cm on day 5, and 10 cm on day 10. Describe the trend.",answer:"The seedling grows steadily by 3 cm every five days.",explanation:"The height rises by the same amount during both intervals."},{id:"gs-d2",type:"short_response",prompt:"Using the seedling data, find the average growth per day from day 0 to day 10.",answer:"0.6 cm per day",explanation:"The total change is 10 − 4 = 6 cm across 10 days, so 6 ÷ 10 = 0.6."},{id:"gs-d3",type:"multiple_choice",prompt:"Which value would be an outlier in the sequence 18, 19, 19, 20, 41?",choices:["18","19","20","41"],answer:"41",explanation:"41 is far from the cluster between 18 and 20."},{id:"gs-d4",type:"multiple_choice",prompt:"Plants under blue light averaged 14 cm; plants under red light averaged 11 cm. What is directly supported?",choices:["Blue light always makes every plant taller","The blue-light group averaged 3 cm taller","Red light prevents growth","Light color is the only factor affecting height"],answer:"The blue-light group averaged 3 cm taller",explanation:"That statement reports the observed group difference without claiming more than the data show."},{id:"gs-d5",type:"constructed_response",prompt:"A class tested only six plants per group. Explain one limitation and one useful next step.",answer:"The small sample may not represent other plants; repeat with more plants under the same controlled conditions.",explanation:"The response identifies sample size as a limit and proposes a larger controlled replication."}],masteryPercent:80,evidenceRequired:"Four correct responses, one shown rate calculation, and a conclusion that acknowledges the study limitation.",correctionPath:["Read every label and unit aloud","Mark the starting and ending values","Write the change as end minus start","Separate observation from explanation","Revise any claim containing always, proves, or only unless the design supports it"],printSections:["Data-reading checklist","Table and graph space","Rate worked example","Independent evidence","Answer explanations"]},{id:"packet-ged-social-history-01",programId:"ged",subject:"Social Studies",moduleId:"social-history",title:"History Through Evidence: Context, Cause, and Source Reliability",estimatedMinutes:60,voiceIntro:"Today we will treat history as an evidence problem. First ask who created the source, when, for whom, and what claim the source can support.",objectives:["Place a source in historical context","Distinguish cause from coincidence","Evaluate purpose and reliability"],vocabulary:["context","primary source","secondary source","cause","reliability"],miniLesson:["A primary source was created during the period being studied; a secondary source interprets later.","Context includes the time, place, events, audience, and conditions surrounding a source.","Cause requires a supported connection, not merely two events happening close together.","A biased source can still be useful when its purpose and limitations are identified."],items:[{id:"gh-h1",type:"multiple_choice",prompt:"Which is a primary source for studying a 1963 march?",choices:["A 2025 textbook chapter","A participant's 1963 diary","A recent documentary","A modern encyclopedia"],answer:"A participant's 1963 diary",explanation:"The diary was created by a participant during the historical period."},{id:"gh-h2",type:"short_response",prompt:"A factory owner writes that working conditions are excellent. What should a historian investigate before accepting the claim?",answer:"The owner's purpose and workers' accounts or inspection records.",explanation:"The owner has a possible interest in presenting the factory positively, so corroboration is needed."},{id:"gh-h3",type:"multiple_choice",prompt:"Event A happened before Event B. What else is needed to claim A caused B?",choices:["A longer timeline","Evidence of a mechanism or connection","A famous quotation","A map"],answer:"Evidence of a mechanism or connection",explanation:"Sequence alone does not establish causation."},{id:"gh-h4",type:"short_response",prompt:"Why might a campaign speech be useful even if it is biased?",answer:"It reveals what the candidate wanted the audience to believe and which issues were emphasized.",explanation:"Purpose and bias are historical evidence when interpreted carefully."},{id:"gh-h5",type:"constructed_response",prompt:"Source A is a government report with statistics. Source B is a resident letter describing one experience. Explain how the sources can be used together.",answer:"Use the report for broad patterns and the letter for an individual experience, while checking the methods and representativeness of each.",explanation:"The sources answer different questions and can corroborate or complicate each other."}],masteryPercent:80,evidenceRequired:"Four correct responses plus a source comparison that identifies both value and limitation.",correctionPath:["Identify creator, date, audience, and purpose","Label the source primary or secondary","Separate what the source states from what you infer","Find a second source that could confirm or challenge it","Rewrite the claim with an accurate limit"],printSections:["Source-analysis frame","Timeline space","Cause-versus-sequence reminder","Independent comparison","Answer explanations"]},{id:"packet-a1-equations-01",programId:"algebra-1",subject:"Algebra I",moduleId:"a1-equations",title:"Keep It Balanced: Equations and Inequalities",estimatedMinutes:60,voiceIntro:"An equation is a balanced statement. Whatever operation you use on one side must also be used on the other side. Say each move before you write it.",objectives:["Solve multi-step equations","Check solutions by substitution","Solve and graph one-variable inequalities"],vocabulary:["equation","inverse operation","solution","inequality","coefficient"],miniLesson:["Simplify each side before undoing operations.","Use inverse operations in reverse order while preserving equality.","Check an equation solution by substituting it into the original equation.","Reverse the inequality sign only when multiplying or dividing both sides by a negative number."],items:[{id:"a1e-1",type:"short_response",prompt:"Solve the equation 3x + 7 = 25 and show each balancing step.",answer:"x = 6",explanation:"Subtract 7 to get 3x = 18, then divide by 3."},{id:"a1e-2",type:"short_response",prompt:"Solve 4(x − 2) = 2x + 10.",answer:"x = 9",explanation:"Distribute: 4x − 8 = 2x + 10. Subtract 2x, add 8, and divide: 2x = 18."},{id:"a1e-3",type:"multiple_choice",prompt:"Which value checks 5x − 4 = 21?",choices:["3","4","5","6"],answer:"5",explanation:"Substitute 5: 5(5) − 4 = 25 − 4 = 21."},{id:"a1e-4",type:"short_response",prompt:"Solve the inequality −2x > 10 and explain the direction of the sign.",answer:"x < −5",explanation:"Divide by −2 and reverse the inequality sign."},{id:"a1e-5",type:"constructed_response",prompt:"A repair service charges $35 plus $18 per hour. Write and solve an equation for a $125 bill.",answer:"35 + 18h = 125; h = 5",explanation:"Subtract 35 to get 18h = 90, then divide by 18. The service lasted 5 hours."}],masteryPercent:80,evidenceRequired:"Four correct solutions, one substitution check, and a verbal or written explanation of the inequality reversal.",correctionPath:["Name the operation attached to the variable","Undo operations on both sides","Write one line per move","Substitute the result","Solve a parallel problem with new numbers"],printSections:["Balance model","Worked equation","Guided set","Independent evidence","Correction and teach-back"]},{id:"packet-a2-complex-quadratics-01",programId:"algebra-2",subject:"Algebra II",moduleId:"a2-complex-quadratics",title:"Quadratic Tools: Completing the Square, Formula, and Complex Solutions",estimatedMinutes:60,voiceIntro:"Quadratic equations can have two real answers, one repeated answer, or two complex answers. We will use the discriminant to predict the result before solving.",objectives:["Use the discriminant to classify solutions","Solve with the quadratic formula","Interpret complex solutions accurately"],vocabulary:["quadratic","discriminant","complex number","imaginary unit","double root"],miniLesson:["Write the equation in ax² + bx + c = 0 form before choosing a method.","The discriminant b² − 4ac predicts two, one, or no real solutions.","The quadratic formula is x = (−b ± √(b² − 4ac)) / 2a.","When the discriminant is negative, use i = √−1 and report a conjugate pair."],items:[{id:"a2q-1",type:"multiple_choice",prompt:"For x² − 6x + 9 = 0, what does the discriminant show?",choices:["Two real roots","One repeated real root","Two complex roots","No equation"],answer:"One repeated real root",explanation:"The discriminant is 36 − 36 = 0."},{id:"a2q-2",type:"short_response",prompt:"Solve x² − 5x + 6 = 0.",answer:"x = 2 or x = 3",explanation:"Factor as (x − 2)(x − 3) = 0."},{id:"a2q-3",type:"short_response",prompt:"Find the discriminant of 2x² + 3x + 5 = 0.",answer:"−31",explanation:"b² − 4ac = 3² − 4(2)(5) = 9 − 40 = −31."},{id:"a2q-4",type:"short_response",prompt:"Solve the quadratic equation x² + 4 = 0 using complex numbers.",answer:"x = ±2i",explanation:"x² = −4, so x = ±√−4 = ±2i."},{id:"a2q-5",type:"constructed_response",prompt:"Explain why x² + 2x + 5 = 0 has no real x-intercepts and give its solutions.",answer:"The discriminant is −16, so there are no real roots; x = −1 ± 2i.",explanation:"A negative discriminant gives a complex conjugate pair and the graph does not cross the real x-axis."}],masteryPercent:80,evidenceRequired:"Four correct results with discriminant work shown and a correct explanation connecting negative discriminant to the graph.",correctionPath:["Rewrite in standard form","Label a, b, and c with signs","Calculate the discriminant separately","Predict the solution type","Substitute carefully into the selected method and verify"],printSections:["Method decision tree","Quadratic-formula reference","Guided discriminants","Independent solutions","Graph connection and correction"]},{id:"packet-chem-atomic-01",programId:"chemistry",subject:"High School Chemistry",moduleId:"chem-atomic",title:"Inside the Atom: Structure, Isotopes, Ions, and Periodic Patterns",estimatedMinutes:60,voiceIntro:"Atoms are too small to see directly, so chemistry uses models and measured evidence. Today we will read atomic notation and use the periodic table as a pattern map.",objectives:["Determine protons, neutrons, and electrons","Distinguish isotopes from ions","Use periodic position to predict properties"],vocabulary:["proton","neutron","electron","isotope","ion"],miniLesson:["Atomic number equals the number of protons and identifies the element.","Mass number equals protons plus neutrons.","Isotopes have the same protons but different neutrons.","Ions form when atoms gain or lose electrons; periodic groups reveal useful valence patterns."],items:[{id:"ca-1",type:"short_response",prompt:"Carbon-14 has atomic number 6. How many protons and neutrons does it have?",answer:"6 protons and 8 neutrons",explanation:"Protons equal atomic number 6; neutrons equal 14 − 6 = 8."},{id:"ca-2",type:"multiple_choice",prompt:"Which pair represents isotopes of the same element?",choices:["6p, 6n and 7p, 6n","8p, 8n and 8p, 10n","11p, 12n and 12p, 11n","1p, 0n and 2p, 0n"],answer:"8p, 8n and 8p, 10n",explanation:"They have the same proton count but different neutron counts."},{id:"ca-3",type:"short_response",prompt:"A neutral sodium atom has 11 electrons. How many electrons are in Na⁺?",answer:"10 electrons",explanation:"A +1 ion has lost one electron."},{id:"ca-4",type:"multiple_choice",prompt:"Elements in the same periodic-table group tend to have similar chemical behavior because they have similar what?",choices:["Mass numbers","Valence-electron patterns","Numbers of neutrons","Physical sizes only"],answer:"Valence-electron patterns",explanation:"Group behavior is strongly related to the arrangement of outer electrons."},{id:"ca-5",type:"constructed_response",prompt:"Compare chlorine-35, chlorine-37, and chloride ion Cl⁻ using protons, neutrons, and electrons.",answer:"All have 17 protons. Cl-35 has 18 neutrons; Cl-37 has 20. A chloride ion has gained one electron, so it has 18 electrons.",explanation:"Isotope names change neutron count; ion charge changes electron count, not element identity."}],masteryPercent:80,evidenceRequired:"Four correct responses plus a particle-count table that distinguishes isotope changes from ion changes.",correctionPath:["Locate atomic number","Write protons first","Subtract to find neutrons","Use charge to adjust electrons","Explain whether the change makes an isotope or an ion"],printSections:["Particle-count organizer","Periodic-table navigation","Worked isotope example","Independent evidence","Answer explanations"],safetyNote:"This packet is model- and data-based. Do not use chemicals or conduct an unsupervised practical activity."},{id:"packet-ged-math-algebra-02",programId:"ged",subject:"Mathematical Reasoning",moduleId:"math-algebra",title:"Algebra in Real Life: Expressions, Equations, and Inequalities",estimatedMinutes:60,voiceIntro:"Today we will turn everyday situations into algebra, solve one careful step at a time, and check each answer in the original situation.",objectives:["Translate words into algebraic expressions","Solve linear equations and inequalities","Check solutions in context"],vocabulary:["variable","coefficient","expression","equation","inequality"],miniLesson:["A variable represents an unknown or changing quantity.","An equation states that two expressions have equal value.","Use inverse operations on both sides to preserve equality.","A solution must satisfy the original statement and make sense in context."],items:[{id:"gm-a1",type:"multiple_choice",prompt:"Which expression represents a $25 fee plus $12 for each hour h?",choices:["25h + 12","12h + 25","37h","25(h + 12)"],answer:"12h + 25",explanation:"The hourly charge is multiplied by h, while the fixed fee is added once."},{id:"gm-a2",type:"short_response",prompt:"Solve 4x + 9 = 37 and show the balancing steps.",answer:"x = 7",explanation:"Subtract 9 from both sides to get 4x = 28, then divide both sides by 4."},{id:"gm-a3",type:"short_response",prompt:"Solve 3(x − 2) = 21 and check the answer.",answer:"x = 9",explanation:"Divide by 3 to get x − 2 = 7, then add 2. Substitution gives 3(9 − 2) = 21."},{id:"gm-a4",type:"multiple_choice",prompt:"A van holds no more than 15 riders. If 9 seats are filled, which inequality describes additional riders r?",choices:["r + 9 ≤ 15","r + 9 ≥ 15","9r ≤ 15","r − 9 ≤ 15"],answer:"r + 9 ≤ 15",explanation:"No more than means the total must be less than or equal to 15."},{id:"gm-a5",type:"constructed_response",prompt:"A worker has $160 and saves $35 each week. Write and solve an equation for when the total reaches $405.",answer:"160 + 35w = 405; w = 7",explanation:"Subtract 160 to get 35w = 245, then divide by 35. Seven weeks gives the stated total."}],masteryPercent:80,evidenceRequired:"Four correct responses, visible balancing steps, and one contextual check written or recorded in the learner's own words.",correctionPath:["Name the unknown","Translate one phrase at a time","Use the same operation on both sides","Substitute the result","Explain whether it fits the situation"],printSections:["Word-to-symbol guide","Worked equation","Guided practice","Independent evidence","Answer and correction page"]},{id:"packet-ged-rla-argument-02",programId:"ged",subject:"Reasoning Through Language Arts",moduleId:"rla-argument",title:"Build the Case: Claims, Evidence, Reasoning, and Counterclaims",estimatedMinutes:60,voiceIntro:"Today we will separate what an author claims from the evidence offered, then judge whether the reasoning really connects the two.",objectives:["Identify claims and supporting evidence","Evaluate reasoning and source strength","Respond to a counterclaim"],vocabulary:["claim","evidence","reasoning","counterclaim","credibility"],miniLesson:["A claim is a position that can be supported or challenged.","Relevant evidence directly addresses the claim; sufficient evidence provides enough support.","Reasoning explains why the evidence supports the claim.","A strong response represents a counterclaim fairly before answering it."],items:[{id:"gr-a1",type:"multiple_choice",prompt:"An author says the library should open later. Which statement is the claim?",choices:["The library recorded visits","The library should open later","Students completed a survey","Evening hours were tested"],answer:"The library should open later",explanation:"The claim is the position the author wants the reader to accept."},{id:"gr-a2",type:"multiple_choice",prompt:"Which evidence best supports later library hours for working adults?",choices:["The building is brick","A survey found 68% could visit only after 6 p.m.","The library owns computers","The director likes evenings"],answer:"A survey found 68% could visit only after 6 p.m.",explanation:"The survey directly connects working adults' availability to evening access."},{id:"gr-a3",type:"short_response",prompt:"Explain why one anonymous online comment is weaker than a documented survey of 400 residents.",answer:"The comment is unverified and represents one person, while the documented survey has a larger, described sample.",explanation:"Credibility and representativeness affect how strongly evidence can support a broad claim."},{id:"gr-a4",type:"short_response",prompt:"State one reasonable counterclaim to extending library hours.",answer:"Longer hours may increase staffing and utility costs.",explanation:"A useful counterclaim directly challenges the proposal with a plausible concern."},{id:"gr-a5",type:"constructed_response",prompt:"Write a short argument supporting a one-month evening-hours trial using the survey evidence and answering the cost counterclaim.",answer:"Because 68% of surveyed residents can visit only after 6 p.m., a one-month trial would test demand. Limiting it to a trial controls cost while producing attendance data.",explanation:"The response uses relevant evidence, connects it to the claim, and answers the cost concern proportionally."}],masteryPercent:80,evidenceRequired:"Four correct responses and a short argument containing a clear claim, relevant evidence, reasoning, and a fair counterclaim response.",correctionPath:["Box the claim","Underline the evidence","Write how the evidence connects","Check source and sample","Revise the counterclaim response fairly"],printSections:["Claim-evidence-reasoning organizer","Source checklist","Counterclaim frame","Independent argument","Answer explanations"]},{id:"packet-ged-science-life-02",programId:"ged",subject:"Science",moduleId:"science-life",title:"Living Systems: Cells, Inheritance, and Ecosystem Change",estimatedMinutes:60,voiceIntro:"Today we will use models and evidence to connect what happens inside cells with inherited traits and changes across an ecosystem.",objectives:["Connect cell structures to functions","Interpret a simple inheritance model","Predict ecosystem effects using evidence"],vocabulary:["cell","gene","allele","producer","population"],miniLesson:["Cell structures perform specialized jobs that keep organisms alive.","Genes carry inherited information, while environment can also affect traits.","Producers capture energy that moves through food webs.","Changing one population can affect several connected populations."],items:[{id:"gs-l1",type:"multiple_choice",prompt:"Which cell structure releases usable energy from food?",choices:["Nucleus","Mitochondrion","Cell wall","Chromosome"],answer:"Mitochondrion",explanation:"Mitochondria carry out cellular respiration that releases usable energy."},{id:"gs-l2",type:"short_response",prompt:"Explain one difference between a gene and an observable trait.",answer:"A gene is inherited information; a trait is a characteristic produced through genes and often environmental influences.",explanation:"The answer distinguishes stored biological information from the resulting observable characteristic."},{id:"gs-l3",type:"multiple_choice",prompt:"If B is dominant and b is recessive, which genotype shows the recessive trait?",choices:["BB","Bb","bB","bb"],answer:"bb",explanation:"A recessive trait appears only when both inherited alleles are recessive."},{id:"gs-l4",type:"short_response",prompt:"Grass feeds rabbits, and rabbits feed hawks. Predict one immediate effect if rabbit numbers sharply decline.",answer:"Hawks may have less food and decline, while grass may increase.",explanation:"Food-web links support both predictions without claiming every other factor is fixed."},{id:"gs-l5",type:"constructed_response",prompt:"A wetland loses half its plant cover after construction. Give a claim, two likely ecosystem effects, and one measurement to collect.",answer:"Habitat quality will decline; herbivore food and shelter may fall and erosion may rise. Measure plant cover and animal abundance over time.",explanation:"The response traces evidence-based effects and proposes measurable follow-up data."}],masteryPercent:80,evidenceRequired:"Four correct responses plus a food-web or habitat explanation containing a supported prediction and a measurable follow-up.",correctionPath:["Name the biological level","Draw the connection","Separate inherited information from outcome","Trace one ecosystem change at a time","Limit the claim to the evidence"],printSections:["Cell-function map","Inheritance model","Food-web workspace","Independent evidence","Answer explanations"]},{id:"packet-ged-social-economics-02",programId:"ged",subject:"Social Studies",moduleId:"social-economics",title:"Everyday Economics: Choices, Markets, and Public Decisions",estimatedMinutes:60,voiceIntro:"Today we will follow how limited resources create choices for households, businesses, and governments, then use data to judge tradeoffs.",objectives:["Explain scarcity and opportunity cost","Interpret supply-and-demand changes","Evaluate a public economic choice"],vocabulary:["scarcity","opportunity cost","supply","demand","inflation"],miniLesson:["Scarcity means resources are limited relative to wants.","Opportunity cost is the next-best option given up.","Price and quantity often change as supply or demand shifts.","Economic policies create benefits, costs, and different effects across groups."],items:[{id:"gh-e1",type:"short_response",prompt:"A city uses $200,000 for road repair instead of a new playground. What is the opportunity cost?",answer:"The new playground or the benefits it would have provided.",explanation:"Opportunity cost is the next-best alternative forgone when the road project is selected."},{id:"gh-e2",type:"multiple_choice",prompt:"Demand for apartments rises while supply stays fixed. What is the most likely short-term result?",choices:["Rents fall","Rents rise","All apartments disappear","Demand becomes zero"],answer:"Rents rise",explanation:"More buyers competing for the same supply tends to increase price."},{id:"gh-e3",type:"multiple_choice",prompt:"Which situation is most likely to increase the supply of local vegetables?",choices:["A drought damages farms","More farms begin producing","Fuel costs rise sharply","A disease harms crops"],answer:"More farms begin producing",explanation:"Additional producers can offer a greater quantity to the market."},{id:"gh-e4",type:"short_response",prompt:"If prices rise 6% while wages rise 2%, what happens to purchasing power, all else equal?",answer:"Purchasing power falls because prices rose faster than wages.",explanation:"Income buys less when its growth does not keep pace with the general price increase."},{id:"gh-e5",type:"constructed_response",prompt:"A city considers reduced bus fares. State one likely benefit, one cost, and one piece of evidence needed before deciding.",answer:"Access and ridership may rise, but fare revenue may fall. Collect ridership, operating-cost, and rider-income data.",explanation:"A sound policy analysis identifies tradeoffs and requests evidence tied to both impact and feasibility."}],masteryPercent:80,evidenceRequired:"Four correct responses plus a public-choice analysis that states a benefit, cost, affected group, and relevant evidence.",correctionPath:["Name the scarce resource","Identify the next-best alternative","Decide whether supply or demand changed","Use the data rather than a slogan","State both benefit and cost"],printSections:["Choice-and-cost organizer","Supply-demand guide","Data interpretation","Policy tradeoff response","Answer explanations"]},{id:"packet-a1-linear-02",programId:"algebra-1",subject:"Algebra I",moduleId:"a1-linear",title:"Lines Tell a Story: Rate, Starting Value, Graphs, and Models",estimatedMinutes:60,voiceIntro:"Today we will connect a table, graph, equation, and real situation so slope means a rate and the intercept means a starting value.",objectives:["Calculate and interpret slope","Write a linear equation from data","Compare linear representations"],vocabulary:["slope","intercept","rate of change","linear","function"],miniLesson:["Slope is change in output divided by change in input.","In y = mx + b, m is slope and b is the value when x equals zero.","A constant rate produces a straight-line pattern.","Units give slope and intercept their contextual meaning."],items:[{id:"a1l-1",type:"short_response",prompt:"Find the slope through points (2, 5) and (6, 13).",answer:"2",explanation:"The change in y is 8 and the change in x is 4, so slope is 8 ÷ 4 = 2."},{id:"a1l-2",type:"multiple_choice",prompt:"In C = 18h + 40, what does 40 represent for a service charge?",choices:["Hourly rate","Starting fee","Hours worked","Maximum cost"],answer:"Starting fee",explanation:"The intercept is the cost when h equals zero, so it is the fixed starting fee."},{id:"a1l-3",type:"short_response",prompt:"A table shows x: 0, 2, 4 and y: 3, 9, 15. Write the linear equation.",answer:"y = 3x + 3",explanation:"The output rises 6 when input rises 2, so slope is 3; y is 3 when x is zero."},{id:"a1l-4",type:"multiple_choice",prompt:"Which description is linear?",choices:["Adds 5 each step","Doubles each step","Squares each input","Changes unpredictably"],answer:"Adds 5 each step",explanation:"Adding the same amount for equal input intervals gives a constant rate of change."},{id:"a1l-5",type:"constructed_response",prompt:"Plan A costs $30 plus $8 per visit. Plan B costs $12 per visit. Find when costs are equal and explain which is cheaper before then.",answer:"30 + 8v = 12v, so v = 7.5; Plan B is cheaper for fewer than 7.5 visits.",explanation:"The intersection represents equal cost, and comparing a smaller visit count confirms Plan B starts cheaper."}],masteryPercent:80,evidenceRequired:"Four correct responses plus one model shown as an equation with labeled slope, intercept, units, and contextual interpretation.",correctionPath:["Mark input and output","Calculate change over change","Find the value at zero","Check two points","Explain every parameter with units"],printSections:["Four-representation organizer","Slope worked example","Guided table","Independent model","Answer explanations"]},{id:"packet-a2-polynomials-02",programId:"algebra-2",subject:"Algebra II",moduleId:"a2-polynomials",title:"Polynomial Behavior: Factors, Zeros, Multiplicity, and Graph Shape",estimatedMinutes:60,voiceIntro:"Today we will use factors and zeros to predict where a polynomial graph crosses or touches the axis and how its ends behave.",objectives:["Connect factors and zeros","Use multiplicity to predict graph behavior","Analyze polynomial end behavior"],vocabulary:["polynomial","factor","zero","multiplicity","end behavior"],miniLesson:["If x − r is a factor, then r is a zero of the polynomial.","Odd multiplicity usually crosses the axis; even multiplicity usually touches and turns.","Degree and leading coefficient determine end behavior.","Substitution or division verifies a proposed zero."],items:[{id:"a2p-1",type:"short_response",prompt:"List the zeros of f(x) = (x − 3)(x + 2).",answer:"x = 3 and x = −2",explanation:"Set each factor equal to zero to find the x-values where the product is zero."},{id:"a2p-2",type:"multiple_choice",prompt:"At x = 4, the factor (x − 4)² gives which graph behavior?",choices:["Crosses the axis","Touches and turns","Has no zero","Becomes linear"],answer:"Touches and turns",explanation:"The zero has even multiplicity two, which typically makes the graph touch and reverse direction."},{id:"a2p-3",type:"short_response",prompt:"Use substitution to verify whether 2 is a zero of p(x) = x³ − 4x.",answer:"Yes; p(2) = 8 − 8 = 0",explanation:"A value is a zero when substitution makes the polynomial equal zero."},{id:"a2p-4",type:"multiple_choice",prompt:"What is the end behavior of an even-degree polynomial with a positive leading coefficient?",choices:["Both ends rise","Both ends fall","Left rises and right falls","Left falls and right rises"],answer:"Both ends rise",explanation:"Positive even-degree leading behavior approaches positive infinity on both ends."},{id:"a2p-5",type:"constructed_response",prompt:"Analyze f(x) = (x + 1)(x − 2)²: give zeros, multiplicities, crossing behavior, and degree.",answer:"Zeros are −1 with multiplicity 1 and 2 with multiplicity 2; it crosses at −1, touches at 2, and has degree 3.",explanation:"Each factor identifies a zero and exponent; the exponents sum to the polynomial degree."}],masteryPercent:80,evidenceRequired:"Four correct responses plus a justified polynomial sketch labeling every zero, multiplicity, crossing behavior, and end behavior.",correctionPath:["Factor completely","Set each factor to zero","Record multiplicity","Use degree and leading sign","Verify one zero by substitution"],printSections:["Factor-zero map","Multiplicity sketches","End-behavior guide","Independent analysis","Answer explanations"]},{id:"packet-chem-bonding-02",programId:"chemistry",subject:"High School Chemistry",moduleId:"chem-bonding",title:"Why Materials Behave Differently: Bonding, Shape, and Properties",estimatedMinutes:60,voiceIntro:"Today we will use electron models to compare ionic, covalent, and metallic bonding and explain why their materials have different properties.",objectives:["Compare major bond types","Build simple Lewis electron models","Connect structure to observable properties"],vocabulary:["ionic bond","covalent bond","metallic bond","valence electron","Lewis structure"],miniLesson:["Ionic bonding involves attraction between oppositely charged ions.","Covalent bonding shares electron pairs between atoms.","Metallic bonding allows mobile electrons through a metal structure.","Bonding and particle arrangement help explain conductivity, melting point, and brittleness."],items:[{id:"cb-1",type:"multiple_choice",prompt:"Which bonding model best describes sodium chloride?",choices:["Ionic attraction","Shared molecular electrons","Metallic electron sea","No particle interaction"],answer:"Ionic attraction",explanation:"Sodium and chlorine form oppositely charged ions that attract in a crystal lattice."},{id:"cb-2",type:"short_response",prompt:"Explain why copper conducts electricity using a metallic-bonding model.",answer:"Its valence electrons can move through the metal structure and carry charge.",explanation:"Mobile electrons are the structural feature that accounts for electrical conductivity."},{id:"cb-3",type:"multiple_choice",prompt:"In a covalent bond, atoms primarily do what with valence electrons?",choices:["Share them","Destroy them","Turn them into protons","Remove all of them"],answer:"Share them",explanation:"A covalent bond is modeled as one or more shared pairs of valence electrons."},{id:"cb-4",type:"short_response",prompt:"Why can an ionic crystal conduct when melted but usually not as a solid?",answer:"Its ions are fixed in the solid but become mobile when melted.",explanation:"Electrical current requires charged particles that can move through the material."},{id:"cb-5",type:"constructed_response",prompt:"Compare table salt, sugar, and copper by bonding type and predict one property of each.",answer:"Salt is ionic and brittle with a high melting point; sugar is molecular covalent and does not conduct; copper is metallic and conducts well.",explanation:"The comparison connects particle models to distinct, testable material properties."}],masteryPercent:80,evidenceRequired:"Four correct responses plus three labeled particle or Lewis models connected to a justified property prediction.",correctionPath:["Count valence electrons","Identify element types","Choose transfer, sharing, or mobile-electron model","Draw the particles","Connect one structural feature to one property"],printSections:["Bond comparison chart","Lewis-model guide","Particle diagrams","Independent property claim","Answer explanations"],safetyNote:"Use diagrams, simulations, or approved dry samples only. Do not heat, taste, dissolve, or electrically test household substances."},{id:"packet-ged-math-graphs-03",programId:"ged",subject:"Mathematical Reasoning",moduleId:"math-graphs",title:"Read the Relationship: Tables, Graphs, Functions, and Change",estimatedMinutes:60,voiceIntro:"Today we will move between tables, graphs, and equations, describe how quantities change, and use labels and units to defend every conclusion.",objectives:["Interpret coordinates and graph features","Recognize functions and rates of change","Compare two represented relationships"],vocabulary:["coordinate","function","slope","intercept","domain"],miniLesson:["An ordered pair connects one input to one output.","A function assigns each input exactly one output.","Slope measures output change per unit of input.","Graph scale, labels, intercepts, and domain determine contextual meaning."],items:[{id:"gm-f1",type:"short_response",prompt:"A line passes through (1, 4) and (5, 12). Find its slope.",answer:"2",explanation:"Output changes by 8 while input changes by 4, so the slope is 8 divided by 4."},{id:"gm-f2",type:"multiple_choice",prompt:"Which relation is a function?",choices:["(1,2), (1,3)","(1,2), (2,3)","(2,4), (2,5)","(3,1), (3,7)"],answer:"(1,2), (2,3)",explanation:"Each input appears only once and therefore has exactly one output."},{id:"gm-f3",type:"short_response",prompt:"In y = 6x + 15, interpret 6 and 15 for a delivery charge.",answer:"$6 per unit and a $15 starting fee",explanation:"The slope is the changing rate, while the intercept is the value when x is zero."},{id:"gm-f4",type:"multiple_choice",prompt:"A graph rises steeply from left to right. Which statement is supported?",choices:["The rate is positive","The intercept is zero","The relation is not a function","All values are negative"],answer:"The rate is positive",explanation:"A left-to-right rise indicates output increases as input increases."},{id:"gm-f5",type:"constructed_response",prompt:"Plan A is y = 10x + 20 and Plan B is y = 14x. Find their intersection and explain which plan costs less before it.",answer:"They meet at x = 5 and y = 70; Plan B costs less before five units.",explanation:"Set equations equal: 10x + 20 = 14x, so x = 5; checking x = 1 shows Plan B is lower."}],masteryPercent:80,evidenceRequired:"Four correct responses plus a labeled comparison using slope, intercept, intersection, units, and a contextual conclusion.",correctionPath:["Read labels and scale","Identify input and output","Calculate change over change","Check a point","State the meaning with units"],printSections:["Coordinate guide","Function check","Graph workspace","Independent comparison","Answer explanations"]},{id:"packet-ged-rla-language-03",programId:"ged",subject:"Reasoning Through Language Arts",moduleId:"rla-language",title:"Make Every Sentence Work: Clarity, Grammar, and Revision",estimatedMinutes:60,voiceIntro:"Today we will revise sentences so readers can follow the meaning easily, using grammar and punctuation as tools rather than as isolated rules.",objectives:["Correct sentence boundaries","Maintain agreement and consistent tense","Revise for clarity and concision"],vocabulary:["clause","fragment","run-on","agreement","modifier"],miniLesson:["A complete sentence contains an independent clause.","Join independent clauses with correct punctuation and connection words.","Subjects and verbs agree in number, and verb tense should remain purposeful.","Place modifiers near the words they describe and remove unnecessary repetition."],items:[{id:"gr-l1",type:"multiple_choice",prompt:"Which revision correctly joins the sentences: The bus was late. We arrived on time.",choices:["The bus was late, we arrived on time.","The bus was late; however, we arrived on time.","The bus was late however we arrived.","Because the bus was late."],answer:"The bus was late; however, we arrived on time.",explanation:"The semicolon and transition correctly join two complete contrasting clauses."},{id:"gr-l2",type:"short_response",prompt:"Correct the agreement error: The list of repairs are on the desk.",answer:"The list of repairs is on the desk.",explanation:"The singular subject list requires the singular verb is."},{id:"gr-l3",type:"multiple_choice",prompt:"Which sentence keeps verb tense consistent?",choices:["She opened the file and checks it.","She opens the file and checked it.","She opened the file and checked it.","She opening the file and checked."],answer:"She opened the file and checked it.",explanation:"Both coordinated actions use the same past-tense form."},{id:"gr-l4",type:"short_response",prompt:"Revise for concision: The final outcome at the end was unexpected.",answer:"The outcome was unexpected.",explanation:"Final and at the end repeat meaning already contained in the word outcome."},{id:"gr-l5",type:"constructed_response",prompt:"Revise this for clarity and explain two changes: Walking into the room, the broken window was noticed by Maya, and she is calling the manager.",answer:"Walking into the room, Maya noticed the broken window and called the manager.",explanation:"Maya now logically performs the opening action, active voice improves clarity, and past tense remains consistent."}],masteryPercent:80,evidenceRequired:"Four correct revisions and one explanation identifying the meaning or readability improved by at least two edits.",correctionPath:["Find the complete clauses","Locate the subject and verb","Check time consistency","Move modifiers beside their targets","Read the revision aloud"],printSections:["Sentence-boundary guide","Agreement checklist","Revision marks","Independent edit","Answer explanations"]},{id:"packet-ged-science-physical-03",programId:"ged",subject:"Science",moduleId:"science-physical",title:"Matter and Motion: Particles, Forces, Energy, and Evidence",estimatedMinutes:60,voiceIntro:"Today we will use particle and force models to explain changes in matter and motion, then connect calculations to observable evidence.",objectives:["Interpret particle models and state changes","Apply force and motion relationships","Track energy transfers"],vocabulary:["matter","density","force","acceleration","energy"],miniLesson:["Matter is modeled as particles whose motion and spacing change with state.","Density compares mass to volume.","A net force changes an object's motion.","Energy transfers between forms while total energy is conserved in a defined system."],items:[{id:"gs-p1",type:"short_response",prompt:"A sample has mass 120 g and volume 40 mL. Find its density.",answer:"3 g/mL",explanation:"Density equals mass divided by volume, so 120 divided by 40 is 3."},{id:"gs-p2",type:"multiple_choice",prompt:"Which particle description best represents a gas?",choices:["Fixed ordered particles","Close particles sliding","Widely spaced moving particles","Particles with no motion"],answer:"Widely spaced moving particles",explanation:"Gas particles move freely and are much farther apart than in solids or liquids."},{id:"gs-p3",type:"short_response",prompt:"A 4 kg cart accelerates at 3 m/s². Find the net force.",answer:"12 N",explanation:"Use force equals mass times acceleration: 4 times 3 equals 12 newtons."},{id:"gs-p4",type:"multiple_choice",prompt:"A rolling ball slows on carpet. Where does much of its kinetic energy go?",choices:["It vanishes","Thermal energy and sound","New mass","Only gravitational energy"],answer:"Thermal energy and sound",explanation:"Friction transfers organized motion energy into thermal energy and some sound."},{id:"gs-p5",type:"constructed_response",prompt:"Compare pushing an empty cart and a loaded cart with the same force. Predict acceleration and explain.",answer:"The empty cart accelerates more because the same force acts on less mass.",explanation:"From a = F/m, increasing mass while force stays fixed reduces acceleration."}],masteryPercent:80,evidenceRequired:"Four correct responses, two calculations with units shown, and one model-based explanation linking force, mass, or energy.",correctionPath:["Name the system","List known values and units","Choose the relationship","Calculate and check units","Explain the physical meaning"],printSections:["Particle models","Formula guide","Force diagram space","Independent evidence","Answer explanations"],safetyNote:"Use simulations or low-risk tabletop demonstrations only; do not use heat, projectiles, open flame, or household electricity."},{id:"packet-ged-social-geography-03",programId:"ged",subject:"Social Studies",moduleId:"social-geography",title:"People and Place: Maps, Movement, Resources, and Regions",estimatedMinutes:60,voiceIntro:"Today we will read maps as evidence, connect human choices to physical geography, and explain movement and resource patterns without overclaiming.",objectives:["Interpret map scale and thematic data","Explain migration push and pull factors","Analyze human-environment relationships"],vocabulary:["region","migration","urbanization","resource","thematic map"],miniLesson:["Maps select and represent information for a purpose.","Scale connects map distance to real distance.","Push factors encourage departure, while pull factors attract people.","Environment shapes choices, and human activity also changes environments."],items:[{id:"gh-g1",type:"short_response",prompt:"A map scale says 1 cm equals 25 km. Two towns are 6 cm apart. Find the real distance.",answer:"150 km",explanation:"Multiply the mapped distance by the scale: 6 times 25 equals 150 kilometers."},{id:"gh-g2",type:"multiple_choice",prompt:"Which is a migration pull factor?",choices:["Crop failure","War","Available jobs","Severe drought"],answer:"Available jobs",explanation:"A pull factor attracts people toward a destination through a perceived opportunity."},{id:"gh-g3",type:"multiple_choice",prompt:"Which map best displays population density by county?",choices:["Political boundary map","Shaded thematic map","Road map only","Elevation profile"],answer:"Shaded thematic map",explanation:"A thematic map can use graduated shading to compare density across areas."},{id:"gh-g4",type:"short_response",prompt:"Give one likely benefit and one risk of building a city beside a major river.",answer:"Benefits include transport or water access; risks include flooding.",explanation:"The response connects settlement choices to both opportunities and physical hazards."},{id:"gh-g5",type:"constructed_response",prompt:"A region's factories close while a nearby city adds healthcare jobs. Explain a likely migration pattern using push and pull factors.",answer:"Workers may leave the factory region because of job loss and move toward the city for healthcare employment.",explanation:"The explanation identifies job loss as a push factor and new employment as a pull factor."}],masteryPercent:80,evidenceRequired:"Four correct responses plus a map- or scenario-based explanation using scale, location evidence, and a limited human-geography claim.",correctionPath:["Read title, legend, and scale","Locate the pattern","Separate push from pull","Name benefit and risk","Limit the claim to mapped evidence"],printSections:["Map-reading checklist","Scale practice","Push-pull organizer","Independent analysis","Answer explanations"]},{id:"packet-a1-systems-03",programId:"algebra-1",subject:"Algebra I",moduleId:"a1-systems",title:"Where Conditions Meet: Systems by Graphing, Substitution, and Elimination",estimatedMinutes:60,voiceIntro:"Today we will find where two conditions are true at the same time, choose an efficient solution method, and interpret the intersection in context.",objectives:["Solve systems using multiple methods","Classify one, none, or infinitely many solutions","Interpret intersections"],vocabulary:["system","intersection","substitution","elimination","solution"],miniLesson:["A system solution makes every equation true.","Graphing shows the intersection visually.","Substitution replaces one variable with an equivalent expression.","Elimination combines equations to remove one variable."],items:[{id:"a1s-1",type:"short_response",prompt:"Solve y = x + 2 and y = 3x − 4 by setting expressions equal.",answer:"(3, 5)",explanation:"Set x + 2 equal to 3x − 4, giving x = 3; substitution gives y = 5."},{id:"a1s-2",type:"multiple_choice",prompt:"Parallel distinct lines have how many system solutions?",choices:["One","None","Two","Infinitely many"],answer:"None",explanation:"Distinct parallel lines never intersect, so no ordered pair satisfies both equations."},{id:"a1s-3",type:"short_response",prompt:"Solve x + y = 10 and x − y = 2 using elimination.",answer:"(6, 4)",explanation:"Adding equations gives 2x = 12, so x = 6; then y = 4."},{id:"a1s-4",type:"multiple_choice",prompt:"Two equations describe the same line. How many solutions exist?",choices:["None","One","Two","Infinitely many"],answer:"Infinitely many",explanation:"Every point on the shared line satisfies both equivalent equations."},{id:"a1s-5",type:"constructed_response",prompt:"Adult tickets cost $12 and youth tickets $7. Fifty tickets total earned $475. Find each number.",answer:"25 adult and 25 youth tickets",explanation:"Use a + y = 50 and 12a + 7y = 475; solving gives a = 25 and y = 25."}],masteryPercent:80,evidenceRequired:"Four correct systems, at least two solution methods shown, both-equation checks, and one contextual interpretation.",correctionPath:["Define both variables","Write both conditions","Choose a method intentionally","Solve and substitute","Check both equations"],printSections:["Method decision guide","Graph workspace","Elimination organizer","Independent model","Answer explanations"]},{id:"packet-a2-rational-radical-03",programId:"algebra-2",subject:"Algebra II",moduleId:"a2-rational-radical",title:"Allowed Answers: Rational Restrictions and Radical Checks",estimatedMinutes:60,voiceIntro:"Today we will identify values that are not allowed, solve rational and radical equations carefully, and reject extraneous answers through checking.",objectives:["State domain restrictions","Solve rational equations","Solve radical equations and check extraneous roots"],vocabulary:["rational expression","radical","domain","restriction","extraneous solution"],miniLesson:["Denominators cannot equal zero.","Multiply rational equations by a valid common denominator.","Isolate a radical before raising both sides to a power.","Algebraic operations can introduce candidates that fail the original equation."],items:[{id:"a2r-1",type:"short_response",prompt:"State the restriction for 5 divided by x minus 3.",answer:"x ≠ 3",explanation:"When x equals 3 the denominator becomes zero, so that value is excluded."},{id:"a2r-2",type:"short_response",prompt:"Solve 1/x = 1/4 and verify the restriction.",answer:"x = 4",explanation:"Cross multiplication gives x = 4, which is allowed because x cannot equal zero."},{id:"a2r-3",type:"multiple_choice",prompt:"Which first step is best for square root of x plus 1 equals 5?",choices:["Square both sides","Divide by x","Add another radical","Set x to zero"],answer:"Square both sides",explanation:"The radical is isolated, so squaring both sides gives x + 1 = 25."},{id:"a2r-4",type:"short_response",prompt:"Solve square root of x plus 1 equals x minus 1 and check candidates.",answer:"x = 3",explanation:"Squaring gives candidates 0 and 3, but substitution shows only 3 satisfies the original equation."},{id:"a2r-5",type:"constructed_response",prompt:"Explain why checking is required after solving an equation containing radicals.",answer:"Squaring both sides can make unequal expressions appear equal and introduce extraneous candidates.",explanation:"The inverse operation is not one-to-one over all real values, so every candidate must be tested."}],masteryPercent:80,evidenceRequired:"Four correct responses with restrictions stated first and every rational or radical candidate checked in the original equation.",correctionPath:["State excluded values","Isolate the fraction or radical","Apply one valid operation","Solve candidates","Substitute into the original"],printSections:["Restriction checklist","Common-denominator guide","Radical workflow","Independent evidence","Answer explanations"]},{id:"packet-chem-reactions-03",programId:"chemistry",subject:"High School Chemistry",moduleId:"chem-reactions",title:"Atoms Rearrange: Evidence, Equations, and Conservation",estimatedMinutes:60,voiceIntro:"Today we will use particle counts and chemical equations to show that reactions rearrange atoms without creating or destroying them.",objectives:["Identify evidence of chemical change","Balance chemical equations","Interpret coefficients and conservation"],vocabulary:["reactant","product","coefficient","subscript","conservation"],miniLesson:["A chemical equation represents reactants changing into products.","Coefficients change particle counts; subscripts define substance identity.","Balanced equations conserve each type of atom.","Temperature, gas, precipitate, or color evidence requires comparison and context."],items:[{id:"cr-1",type:"multiple_choice",prompt:"Which observation most strongly suggests a new substance formed?",choices:["Ice melts","Water boils","A solid precipitate appears","Sugar dissolves"],answer:"A solid precipitate appears",explanation:"Formation of an unexpected insoluble solid can be evidence of a chemical reaction."},{id:"cr-2",type:"short_response",prompt:"Balance H₂ + O₂ → H₂O using whole-number coefficients.",answer:"2H₂ + O₂ → 2H₂O",explanation:"The balanced equation has four hydrogen atoms and two oxygen atoms on each side."},{id:"cr-3",type:"multiple_choice",prompt:"Why must subscripts not be changed when balancing?",choices:["They identify the substance","They show temperature","They are optional labels","They count reaction time"],answer:"They identify the substance",explanation:"Changing a subscript changes the chemical formula and therefore creates a different substance."},{id:"cr-4",type:"short_response",prompt:"Balance N₂ + H₂ → NH₃.",answer:"N₂ + 3H₂ → 2NH₃",explanation:"Two ammonia units conserve two nitrogen atoms and require six hydrogen atoms."},{id:"cr-5",type:"constructed_response",prompt:"Explain conservation using a particle model for 2H₂ + O₂ → 2H₂O.",answer:"Four hydrogen and two oxygen atoms begin in separate molecules and end rearranged into two water molecules.",explanation:"The count of each atom stays constant even though the atoms form different particle groupings."}],masteryPercent:80,evidenceRequired:"Four correct responses plus two balanced equations with atom inventories and a particle-model conservation explanation.",correctionPath:["Write correct formulas","Count each atom","Change coefficients only","Recount both sides","Explain the particle rearrangement"],printSections:["Reaction evidence guide","Atom inventory","Balancing workspace","Independent model","Answer explanations"],safetyNote:"Use equations, videos, or simulations only. Never mix cleaners, unknown substances, acids, bases, heat sources, or sealed reaction containers."}];n.reduce((t,a)=>t+a.items.length,0),n.reduce((t,a)=>t+a.estimatedMinutes,0);function p(t){return n.filter(a=>a.programId===t)}function e(t,a,o,s,r){const c=["Core idea","Model it","Check reasoning","Use context","Plan the release"];return{packetId:t,crashCourse:a.map((l,i)=>({minute:i+1,focus:c[i],briefing:l})),likelyMisconceptions:o,teachingStrategies:[{name:"Model, coach, release",how:"Work one example aloud, solve a parallel example together, then require independent work and a learner teach-back."},{name:"Find the first break",how:"When an answer is wrong, inspect the reasoning line by line and coach the learner to repair the first unsupported step."}],askTheseQuestions:["What do you already know?","Which evidence supports that step?","How will you check the result?"],readyCheck:s,avoid:r}}const d=[{packetId:"packet-ged-math-geometry-01",crashCourse:[{minute:1,focus:"Know the difference",briefing:"Perimeter is distance around, area is surface covered, and volume is three-dimensional space. Units reveal which quantity is being measured."},{minute:2,focus:"Choose the formula",briefing:"Teach the instructor to name the shape, circle the requested quantity, and select the formula before substituting numbers."},{minute:3,focus:"Guard the units",briefing:"Linear answers use units, area uses square units, and volume uses cubic units. Scale problems multiply drawing length by the stated scale."},{minute:4,focus:"Right triangles",briefing:"The Pythagorean relationship applies only to right triangles. The hypotenuse is opposite the right angle and must be the longest side."},{minute:5,focus:"Plan the lesson",briefing:"Model one room-measurement example, solve one together, then let the learner choose and defend a formula independently."}],likelyMisconceptions:["Adding length and width when area is requested","Dropping square or cubic units","Using the Pythagorean relationship on a non-right triangle"],teachingStrategies:[{name:"Formula sort",how:"Give three everyday jobs—fence, floor, box—and have the learner match each to perimeter, area, or volume before calculating."},{name:"Sketch and label",how:"Require a quick picture with dimensions and units so the learner can see what the numbers represent."},{name:"Estimate first",how:"Ask for a reasonable range before exact calculation; use the estimate to catch calculator or formula errors."}],askTheseQuestions:["What are we measuring?","Which units should the answer use?","What makes your answer reasonable?"],readyCheck:"Can you explain the difference between 24 ft, 24 ft², and 24 ft³ without reading the packet?",avoid:"Do not begin with formula memorization. Begin with the real object and the measurement job."},{packetId:"packet-ged-rla-reading-01",crashCourse:[{minute:1,focus:"Central idea",briefing:"The central idea is the point developed across the entire passage, not merely a topic or one interesting detail."},{minute:2,focus:"Text evidence",briefing:"A strong answer names the claim and points to exact words, facts, or examples that support it."},{minute:3,focus:"Inference",briefing:"Inference combines a text clue with reasonable background knowledge. It must remain anchored to the passage."},{minute:4,focus:"Tone and purpose",briefing:"Tone comes from word choice and attitude; purpose asks what the author wants the reader to understand, believe, or do."},{minute:5,focus:"Plan the lesson",briefing:"Read one paragraph aloud, model a think-aloud, annotate a second paragraph together, then release the learner to explain independently."}],likelyMisconceptions:["Restating the topic instead of the central idea","Choosing a true detail that does not answer the question","Calling a personal opinion an inference"],teachingStrategies:[{name:"Somebody wanted but so",how:"For narrative text, use the frame to identify the situation, motivation, obstacle, and outcome before naming the main idea."},{name:"Claim-clue-connection",how:"Require three short lines: my answer, the text clue, and how the clue proves the answer."},{name:"Tone swap",how:"Replace one key word with a positive or negative alternative and discuss how the author's attitude changes."}],askTheseQuestions:["Which words made you think that?","Does this answer the question or only repeat a detail?","What would make another answer weaker?"],readyCheck:"Can you distinguish topic, central idea, supporting detail, and inference using the same short paragraph?",avoid:"Do not tell the learner what a passage means before asking what evidence they notice."},{packetId:"packet-ged-science-data-01",crashCourse:[{minute:1,focus:"Read the frame",briefing:"Always read the title, labels, units, legend, and measurement intervals before interpreting values."},{minute:2,focus:"Describe the pattern",briefing:"A trend is the overall direction. An outlier is a value far from the pattern and should be examined, not automatically deleted."},{minute:3,focus:"Calculate change",briefing:"Change is ending value minus starting value. Average rate divides that change by the elapsed interval."},{minute:4,focus:"Limit the claim",briefing:"Data support statements about the observed groups and conditions. They rarely justify words such as always, proves, or only."},{minute:5,focus:"Plan the lesson",briefing:"Model label-reading, calculate one change together, and have the learner defend one conclusion using two values."}],likelyMisconceptions:["Ignoring units or graph scale","Describing one point instead of the overall trend","Claiming causation when the design shows only an association"],teachingStrategies:[{name:"Notice-wonder-calculate",how:"First ask what the learner notices, then what they wonder, and only then choose the calculation needed."},{name:"Evidence sentence frame",how:"Use: The data support ___ because ___ changed from ___ to ___."},{name:"Overclaim detector",how:"Highlight words such as always and proves, then ask whether the sample and design truly support them."}],askTheseQuestions:["What do the labels and units say?","Which two values support your claim?","What can these data not tell us?"],readyCheck:"Can you calculate a rate of change and explain why a small sample limits a conclusion?",avoid:"Do not turn the lesson into vocabulary recall; keep every term connected to the displayed data."},{packetId:"packet-ged-social-history-01",crashCourse:[{minute:1,focus:"Source type",briefing:"A primary source comes from the period under study; a secondary source interprets the period later."},{minute:2,focus:"Context",briefing:"Source meaning depends on creator, time, place, audience, purpose, and surrounding events."},{minute:3,focus:"Cause",briefing:"One event occurring before another is not enough. Causation requires evidence of a mechanism or supported connection."},{minute:4,focus:"Bias and usefulness",briefing:"Bias does not make a source useless. It changes which questions the source can answer and what corroboration is needed."},{minute:5,focus:"Plan the lesson",briefing:"Model one source using who-when-why, compare a second source together, then let the learner write a limited evidence-based claim."}],likelyMisconceptions:["Assuming primary means accurate","Treating bias as a reason to discard a source","Confusing chronological order with causation"],teachingStrategies:[{name:"Who-when-why",how:"Write the creator, date, audience, and purpose in four boxes before discussing source meaning."},{name:"Source conversation",how:"Ask what two sources agree on, disagree on, and leave unanswered."},{name:"Claim strength ladder",how:"Revise an overconfident claim into a precise claim that names the evidence and its limit."}],askTheseQuestions:["Who created this and for whom?","What can this source reliably show?","Which other source would you want next?"],readyCheck:"Can you explain how a biased source may still be valuable and name the corroborating evidence you would seek?",avoid:"Do not make the activity a trivia test. The target is reasoning from sources, not recalling disconnected dates."},{packetId:"packet-a1-equations-01",crashCourse:[{minute:1,focus:"Equality",briefing:"An equation states that two expressions have equal value. Preserve that equality by performing the same valid operation on both sides."},{minute:2,focus:"Order the moves",briefing:"Simplify each side, undo addition or subtraction, then undo multiplication or division. Write one transformation per line."},{minute:3,focus:"Check",briefing:"Substitute the proposed solution into the original equation. Both sides must evaluate to the same number."},{minute:4,focus:"Inequalities",briefing:"Reverse the inequality direction only when multiplying or dividing both sides by a negative number."},{minute:5,focus:"Plan the lesson",briefing:"Start with a balance model, solve one equation together, use substitution to check it, then contrast an inequality."}],likelyMisconceptions:["Moving a term without understanding the inverse operation","Changing only one side of an equation","Forgetting to reverse an inequality after division by a negative"],teachingStrategies:[{name:"Balance scale",how:"Use cups, counters, or a drawn scale to show that equal changes preserve balance."},{name:"Say the move",how:"Before writing, the learner says: I will subtract seven from both sides because I need to undo plus seven."},{name:"Mistake analysis",how:"Show a believable wrong solution and ask the learner to find the first line where equality was broken."}],askTheseQuestions:["What operation is attached to the variable?","What will undo it on both sides?","How can substitution prove your answer?"],readyCheck:"Can you solve, check, and verbally explain one multi-step equation and one negative-coefficient inequality?",avoid:"Do not teach unexplained phrases such as move it across and change the sign."},{packetId:"packet-a2-complex-quadratics-01",crashCourse:[{minute:1,focus:"Standard form",briefing:"Place the quadratic in ax² + bx + c = 0 form and label a, b, and c with their signs."},{minute:2,focus:"Discriminant",briefing:"The value b² − 4ac predicts two real roots, one repeated real root, or a complex conjugate pair."},{minute:3,focus:"Method choice",briefing:"Use factoring when structure is friendly, square-root methods for isolated squares, and the quadratic formula as the reliable general method."},{minute:4,focus:"Complex meaning",briefing:"When the discriminant is negative, use i = √−1. Complex roots mean the real graph has no x-intercepts."},{minute:5,focus:"Plan the lesson",briefing:"Classify three discriminants first, solve one equation together, and connect the result to the graph before independent practice."}],likelyMisconceptions:["Dropping the sign of b or c","Taking the square root of a negative as a real number","Dividing only one term in the quadratic formula by 2a"],teachingStrategies:[{name:"Discriminant traffic light",how:"Sort positive, zero, and negative discriminants into two real, repeated, and complex solution categories."},{name:"Formula color map",how:"Color-code a, b, and c in the equation and use the same colors when substituting into the formula."},{name:"Graph connection",how:"Sketch whether the parabola crosses, touches, or misses the x-axis before solving."}],askTheseQuestions:["What are a, b, and c including their signs?","What does the discriminant predict?","How should the graph match the solution type?"],readyCheck:"Can you classify the roots from the discriminant and explain why negative discriminant means no real x-intercepts?",avoid:"Do not begin by forcing every problem through memorized formula substitution without predicting the solution type."},{packetId:"packet-chem-atomic-01",crashCourse:[{minute:1,focus:"Element identity",briefing:"Atomic number equals protons. Changing the proton count changes the element."},{minute:2,focus:"Mass and isotopes",briefing:"Mass number equals protons plus neutrons. Isotopes share a proton count but have different neutron counts."},{minute:3,focus:"Ions",briefing:"A neutral atom has equal protons and electrons. Positive ions lose electrons; negative ions gain electrons."},{minute:4,focus:"Periodic patterns",briefing:"Elements in the same group have related valence-electron patterns and often similar chemical behavior."},{minute:5,focus:"Plan the lesson",briefing:"Model one particle-count table, compare an isotope and an ion, then let the learner explain which particle changed and what that means."}],likelyMisconceptions:["Using mass number as the proton count","Changing protons when forming an ion","Thinking a positive ion gained positive particles"],teachingStrategies:[{name:"Particle accounting table",how:"Use columns for atomic number, mass number, charge, protons, neutrons, and electrons; fill them in a fixed order."},{name:"Identity versus condition",how:"Ask whether the change affects element identity, isotope, or charge before doing arithmetic."},{name:"Periodic-table scavenger hunt",how:"Have learners find group neighbors and predict one shared valence behavior using the table."}],askTheseQuestions:["Which particle identifies the element?","Did neutrons or electrons change?","How does the charge tell you the electron count?"],readyCheck:"Can you complete and explain a proton-neutron-electron table for an isotope and an ion without consulting the answer key?",avoid:"Do not use unsupervised chemicals or imply that the simple particle model explains every atomic behavior."},e("packet-ged-math-algebra-02",["A variable names an unknown or changing quantity; translate the situation before selecting any operation.","Preserve equality by applying the same inverse operation to both sides and recording one move per line.","Substitute the proposed value into the original equation because a plausible-looking answer is not sufficient evidence.","Words such as at most and no more than signal an inequality, and the answer must retain its contextual units.","Model one word-to-equation translation, coach one solution, then release a parallel problem for teach-back."],["Combining unlike terms","Changing only one side of an equation","Ignoring inequality language"],"Can you translate, solve, check, and explain a contextual linear equation without relying on move-it-across shortcuts?","Do not reward an isolated number without visible translation, balancing steps, and a contextual check."),e("packet-ged-rla-argument-02",["A claim is the position to be accepted; evidence is the information offered to support that position.","Relevant evidence addresses the claim directly, while sufficient evidence provides enough credible support for its scope.","Reasoning is the bridge between evidence and claim, so ask the learner to state why each fact matters.","A counterclaim should be represented fairly before it is answered with evidence, limits, or a practical compromise.","Model claim-evidence-reasoning once, evaluate a source together, then release a short counterclaim response."],["Treating opinion as evidence","Listing evidence without explaining it","Misrepresenting the counterclaim"],"Can you distinguish claim, evidence, and reasoning, judge source strength, and answer a counterclaim fairly?","Do not turn argument analysis into agreement with the author's opinion; score the quality of support."),e("packet-ged-science-life-02",["Keep the biological level clear: cell structures perform functions, genes carry information, and ecosystems contain interacting populations.","Use a labeled model to show structure and function rather than asking learners to memorize disconnected vocabulary.","Dominant describes expression in a simple allele model and does not mean better, stronger, or more common.","Food-web predictions should trace one connection at a time and remain limited because other ecosystem factors may change.","Model one cell-function link, coach one inheritance question, then release an ecosystem evidence explanation."],["Calling dominant traits stronger","Confusing genes with traits","Predicting one ecosystem effect as certain"],"Can you explain one cell function, one inheritance model, and one limited food-web prediction with evidence?","Do not present simplified inheritance or food webs as complete explanations for every biological outcome."),e("packet-ged-social-economics-02",["Scarcity creates choices because available time, money, labor, and materials cannot satisfy every possible use.","Opportunity cost is the next-best alternative forgone, not every possible alternative or simply the dollar price.","When analyzing markets, identify whether supply or demand changed before predicting price and quantity effects.","Public economic choices distribute benefits and costs differently, so name the affected groups and supporting evidence.","Model one opportunity-cost choice, coach one market shift, then release a balanced policy tradeoff response."],["Calling price the opportunity cost","Moving supply and demand at the same time without evidence","Naming benefits but no costs"],"Can you identify a true opportunity cost, predict one market shift, and evaluate a policy with evidence?","Do not teach markets as automatic moral judgments; keep claims tied to conditions, data, and tradeoffs."),e("packet-a1-linear-02",["Slope is change in output divided by change in input, and its units describe a rate in the real situation.","The intercept is the output when input is zero, often representing a starting amount, fee, or initial condition.","A linear relationship has a constant rate across equal input intervals and should agree in table, graph, and equation.","Comparing two plans means finding their intersection and testing which model is lower on either side of that point.","Model a table-to-equation conversion, coach a contextual interpretation, then release a comparison for teach-back."],["Flipping rise and run","Calling the intercept the rate","Ignoring units or meaningful domain"],"Can you move among table, graph, equation, and context while explaining slope and intercept with units?","Do not let graphing technology replace the learner's explanation of rate, starting value, and domain."),e("packet-a2-polynomials-02",["A factor x minus r identifies a zero r; keep the sign relationship visible when translating between forms.","Multiplicity predicts local behavior: odd multiplicity generally crosses, while even multiplicity touches and turns.","Degree and leading coefficient control the far-left and far-right behavior of a polynomial graph.","Verify a proposed zero by substitution or division before using it to justify a factor or graph feature.","Model one factor-zero map, coach a multiplicity sketch, then release a complete polynomial analysis."],["Reversing the sign of a zero","Ignoring multiplicity","Guessing end behavior from one plotted point"],"Can you identify zeros, multiplicities, crossing behavior, degree, and end behavior from factored form?","Do not accept a calculator graph without algebraic justification for every labeled feature."),e("packet-chem-bonding-02",["Ionic bonding models electrostatic attraction between ions, covalent bonding models shared pairs, and metallic bonding models mobile electrons.","Count valence electrons carefully before drawing a Lewis model, and check that the total electron count is preserved.","Structure explains properties only through a stated mechanism, such as mobile charged particles enabling conductivity.","Distinguish bonds within particles from attractions between particles so melting and boiling explanations remain accurate.","Model one electron diagram, coach one property claim, then release a three-material comparison with evidence."],["Calling every metal-nonmetal sample a molecule","Confusing bond type with intermolecular force","Naming a property without a mechanism"],"Can you build a valid electron model and use a structural mechanism to predict conductivity or melting behavior?","Do not use unsupervised heat, electricity, tasting, or chemical mixing to demonstrate bonding properties."),e("packet-ged-math-graphs-03",["Ordered pairs connect inputs and outputs; confirm graph labels, scale, and units before interpreting any pattern.","Slope is output change divided by input change, while the intercept is the output at an input of zero.","A function gives each input exactly one output, whether represented by points, a table, a graph, or an equation.","Intersections show when two relationships share the same input and output and must be interpreted in context.","Model one graph reading, coach one equation comparison, then release an intersection explanation with units."],["Ignoring graph scale","Confusing slope and intercept","Calling repeated outputs a function violation"],"Can you interpret slope, intercept, function status, and intersection across representations with units?","Do not accept calculator output without labels, scale reading, and contextual meaning."),e("packet-ged-rla-language-03",["Independent clauses can stand alone; fragments cannot, and run-ons join complete clauses without proper connection.","Find the true subject before choosing a verb because intervening phrases do not change subject-verb agreement.","Verb tense should follow the intended time and remain consistent unless the meaning requires a deliberate shift.","Modifiers belong beside the words they describe, while repeated or empty wording should be removed for clarity.","Model one read-aloud revision, coach one sentence-boundary repair, then release a clarity explanation."],["Editing by sound alone","Matching a verb to the nearest noun","Changing meaning while shortening"],"Can you repair boundaries, agreement, tense, and modifiers while explaining how the revision improves meaning?","Do not teach grammar as labels alone; connect every edit to what the reader understands."),e("packet-ged-science-physical-03",["Particle models distinguish solids, liquids, and gases through arrangement, spacing, and motion rather than particle identity.","Density equals mass divided by volume and requires both a numerical result and compound units.","Net force changes motion; for a fixed force, greater mass produces less acceleration according to the model.","Energy changes form and location within a defined system rather than disappearing when motion slows.","Model one unit calculation, coach one force prediction, then release an energy-transfer explanation."],["Dropping compound units","Confusing force with speed","Saying energy disappears"],"Can you calculate density or force with units and explain one particle or energy model accurately?","Do not use unsafe heat, projectiles, mains electricity, or uncontrolled demonstrations."),e("packet-ged-social-geography-03",["Read map title, legend, orientation, projection, and scale because every map represents selected information for a purpose.","Convert mapped distance through the stated scale and retain the correct real-world distance units.","Push factors encourage departure, while pull factors attract people toward a destination; one event can involve both.","Human settlement responds to environmental opportunity and hazard while also changing the environment over time.","Model one scale problem, coach one thematic pattern, then release a limited migration explanation."],["Skipping the legend","Reversing push and pull","Treating map patterns as proof of causation"],"Can you use map scale and thematic evidence to explain a limited migration or settlement pattern?","Do not infer motives, causation, or universal patterns from location alone."),e("packet-a1-systems-03",["A system solution is one ordered pair that makes every equation true, not merely a value that satisfies one equation.","Graphing emphasizes intersection, substitution uses an equivalent expression, and elimination combines equations strategically.","Parallel distinct lines have no solution, while equivalent equations represent the same line and have infinitely many.","Context determines variable definitions, equation structure, units, and which mathematical solutions are meaningful.","Model method selection, coach one elimination, then release a contextual system with a both-equation check."],["Checking only one equation","Calling parallel lines one solution","Using an ordered pair without context"],"Can you choose a method, solve, verify both equations, and interpret the ordered pair in context?","Do not force one method on every system or accept an unchecked intersection."),e("packet-a2-rational-radical-03",["State denominator restrictions before solving because excluded values can never become valid answers later.","For rational equations, multiply every term by a valid least common denominator and preserve restrictions.","For radical equations, isolate one radical before applying a power and track every resulting candidate.","Squaring can introduce extraneous candidates, so substitute each result into the original equation.","Model a restriction check, coach one radical isolation, then release a full solve-and-verify explanation."],["Forgetting excluded values","Squaring only one term","Reporting every algebraic candidate"],"Can you state restrictions, solve rational and radical equations, and reject extraneous candidates by substitution?","Do not call a candidate a solution until it satisfies the original equation and its domain."),e("packet-chem-reactions-03",["Chemical equations name reactants and products, while observations provide evidence that a chemical change may have occurred.","Balance equations by changing coefficients only because changing a subscript changes the identity of a substance.","Use an atom inventory after every coefficient change to verify conservation for each element.","Particle models should show atoms rearranging into new groupings without any atoms appearing or disappearing.","Model one inventory, coach one equation, then release a particle-based conservation explanation."],["Changing subscripts","Balancing one element then failing to recount","Calling every physical change a reaction"],"Can you balance with coefficients, recount every atom, and explain conservation with a particle model?","Do not conduct home reactions or mix cleaners, unknowns, acids, bases, heat, or sealed containers."),e("packet-ged-math-foundations-00",["Fractions, decimals, and percents are three ways of naming the same quantity, so conversion is the first fluency to secure.","Percent problems become reliable when the percent is rewritten as a decimal before any multiplication.","Proportions work because two equal ratios can be cross multiplied to recover one missing value.","Exponents count repeated multiplication and square roots reverse squaring, so order of operations must be enforced.","Model one percent problem, coach one proportion, then release a multi-step money problem with a reasonableness check."],["Multiplying by the whole percent instead of the decimal","Adding across a proportion instead of cross multiplying","Treating an exponent as multiplication by the exponent"],"Can you convert among fraction, decimal, and percent, solve a proportion, and defend an answer as reasonable?","Do not accept a bare number without units, steps, or an estimate check."),e("packet-ged-science-practices-00",["A testable question names a change and a measurable outcome instead of asking for an opinion.","Independent means changed by the investigator; dependent means measured as a result.","Controlled variables protect the comparison, so any unlisted difference weakens the conclusion.","A control group shows what happens without the treatment and makes the comparison meaningful.","Model one variable sort, coach one control list, then release a critique that narrows an overstated claim."],["Swapping independent and dependent variables","Treating a hypothesis as a proven result","Generalizing from one trial or a tiny sample"],"Can you identify variables, explain the control, and judge whether a claim stays inside the evidence?","Do not run chemical, heat, or electrical procedures, and do not let learners accept always or never claims."),e("packet-ged-social-civics-00",["Constitutional principles like popular sovereignty and federalism explain who holds authority and where.","Separation of powers assigns lawmaking, enforcement, and interpretation to three distinct branches.","Checks such as veto, override, and judicial review are how one branch limits another in practice.","GED civics questions are document based, so the answer must be traceable to the supplied source.","Model one quotation analysis, coach one branch-and-check match, then release a participation explanation with cited evidence."],["Naming the branch from memory instead of the document","Confusing judicial review with impeachment","Answering a civics question with personal opinion"],"Can you match powers to branches, identify a check, and support a civics claim with the supplied source?","Do not turn the session into partisan debate or accept an answer with no textual evidence.")],h={packetId:"default",crashCourse:[{minute:1,focus:"Read the goal",briefing:"Name exactly what the learner must understand or produce."},{minute:2,focus:"Review the model",briefing:"Work the packet example and identify each reasoning step."},{minute:3,focus:"Predict errors",briefing:"Choose two likely mistakes and prepare a question that helps the learner self-correct."},{minute:4,focus:"Choose strategies",briefing:"Prepare one visual method and one verbal or step-by-step method."},{minute:5,focus:"Set the evidence",briefing:"Know the mastery rule and what learner work will be recorded."}],likelyMisconceptions:["Rushing without explaining","Copying a procedure without understanding"],teachingStrategies:[{name:"Model then release",how:"I do one, we do one, you do one, then the learner teaches it back."},{name:"Ask before telling",how:"Use a focused question to locate the learner's reasoning before giving another explanation."}],askTheseQuestions:["What do you notice?","Which step is confusing?","How can you check your answer?"],readyCheck:"Can you explain the lesson goal, model one example, and name the evidence required for mastery?",avoid:"Do not lecture through the entire session or treat speed as understanding."};function u(t){return d.find(a=>a.packetId===t)??h}export{n as C,u as a,p};
